import random
from datetime import datetime, timedelta

class IDCard:
    def __init__(self):
        self.name = self.get_name()
        self.date_of_birth = self.get_date_of_birth()
        self.address = self.get_address()
        self.expiration_date = self.get_expiration_date()
        self.issuing_authority = self.get_issuing_authority()

    def get_name(self):
        first_names = ["Alice", "Bob", "Charlie", "David", "Eve"]
        last_names = ["Smith", "Johnson", "Williams", "Jones", "Brown"]
        return f"{random.choice(first_names)} {random.choice(last_names)}"

    def get_date_of_birth(self):
        year = random.randint(1900, 2000)
        month = random.randint(1, 12)
        day = random.randint(1, 28)
        return f"{day}/{month}/{year}"

    def get_address(self):
        street_names = ["123 Main", "456 Elm", "789 Oak"]
        city_names = ["New York", "Los Angeles", "Chicago", "Houston", "Philadelphia"]
        states = ["NY", "CA", "IL", "TX", "PA"]
        zip_codes = ["10001", "10002", "10003", "10004", "10005"]
        return f"{random.choice(street_names)}, {random.choice(city_names)}, {random.choice(states)} {random.choice(zip_codes)}"

    def get_expiration_date(self):
        expiration_date = datetime.now() + timedelta(days=365)
        return f"{expiration_date.month}/{expiration_date.day}/{expiration_date.year}"

    def get_issuing_authority(self):
        issuing_authorities = ["New York State", "California State", "United States Government"]
        return random.choice(issuing_authorities)

    def to_string(self):
        return f"""
ID Card
Name: {self.name}
Date of Birth: {self.date_of_birth}
Address: {self.address}
Expiration Date: {self.expiration_date}
Issuing Authority: {self.issuing_authority}
"""
